export function initHelpChat({account}){
 const button=document.createElement('button');button.type='button';button.className='support-launcher';button.setAttribute('aria-label','Abrir ajuda para tirar dúvidas');button.innerHTML='<img src="/assets/favicon.webp" alt="" width="44" height="44"><span>Dúvidas?</span>';document.body.append(button);
 const dialog=document.createElement('dialog');dialog.className='help-dialog';dialog.setAttribute('aria-labelledby','help-title');dialog.innerHTML="<header class=\"help-header\"><img src=\"/assets/favicon.webp\" alt=\"\" width=\"42\" height=\"42\"><div class=\"help-heading\"><p class=\"help-eyebrow\">CAPIMIMO · AJUDA</p><h2 id=\"help-title\">Como podemos ajudar?</h2><span>Respostas automáticas</span></div><button type=\"button\" class=\"help-close\" aria-label=\"Fechar ajuda\">×</button></header><div class=\"help-messages\" aria-label=\"Conversa\" aria-live=\"polite\"></div><div class=\"help-human\"><button type=\"button\" class=\"help-open-human\">Falar com uma pessoa</button><small>Entre com seu e-mail para acompanhar a resposta em Minha conta.</small></div><details class=\"help-privacy\"><summary>Sobre esta conversa</summary><p>Sua pergunta é processada por IA da Cloudflare. Não envie senhas, códigos de acesso, dados de cartão ou informações pessoais sensíveis.</p></details><form class=\"help-form\"><label for=\"help-question\">Sua mensagem</label><div class=\"help-composer\"><textarea id=\"help-question\" name=\"question\" maxlength=\"500\" rows=\"2\" required placeholder=\"Escreva sua dúvida...\"></textarea><button type=\"submit\" class=\"help-send\" aria-label=\"Enviar mensagem\">Enviar</button></div></form><p class=\"help-status\" role=\"status\"></p>";document.body.append(dialog);
 const $=s=>dialog.querySelector(s),form=$('.help-form'),status=$('.help-status'),messages=$('.help-messages');let version=0,busy=false,lastQuestion='';
 function add(label,text){const item=document.createElement('article'),who=document.createElement('strong'),body=document.createElement('p');who.textContent=label;body.textContent=text;item.className=label==='Você'?'help-message is-user':'help-message is-assistant';item.append(who,body);messages.append(item);item.scrollIntoView({block:'nearest'});}
 function clear(){version++;busy=false;lastQuestion='';form.reset();$('.help-send').disabled=false;status.textContent='';messages.replaceChildren();add('Ajuda automática','Oi! Posso explicar os planos e como criar seu presente. O que você gostaria de saber?');}
 button.addEventListener('click',()=>{if(dialog.open)return;clear();dialog.showModal();$('#help-question').focus();});$('.help-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',clear);
 $('.help-open-human').addEventListener('click',()=>{const draft=$('#help-question').value.trim()||lastQuestion;dialog.close();account.openSupport({draft});});
 form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!form.reportValidity())return;const question=$('#help-question').value.trim();if(!question){status.textContent='Escreva sua pergunta.';return;}const own=++version;busy=true;lastQuestion=question;add('Você',question);$('.help-send').disabled=true;status.textContent='Escrevendo uma resposta…';try{const response=await fetch('/api/help/answer',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({question}),signal:AbortSignal.timeout(30000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Não foi possível responder agora.');if(own!==version||!dialog.open)return;add('Ajuda automática',typeof data.answer==='string'?data.answer:'Fale com nossa equipe para receber ajuda.');form.reset();status.textContent=data.handoff?'Nossa equipe pode ajudar com essa questão.':'Resposta gerada por IA. Confira as informações antes de decidir.';}catch(error){if(own===version&&dialog.open)status.textContent=error.message||'Não foi possível responder agora. Tente novamente ou fale com a equipe.';}finally{if(own===version){busy=false;$('.help-send').disabled=false;}}});
 document.addEventListener('click',event=>{const link=event.target.closest?.('a[href="#ajuda"]');if(link){event.preventDefault();button.click();}});if(location.hash==='#ajuda')queueMicrotask(()=>button.click());
 return {button,dialog};
}
